#include "PluginEditor.h"
#include "WaveComparison.h"
#include <iostream>
#include <set>
namespace {
void check(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
struct Clock : juce::AudioPlayHead {PositionInfo p;juce::Optional<PositionInfo> getPosition() const override{return p;}};
juce::AudioBuffer<float> render(FKickProcessor& p,int block=257,bool clocked=false){
    p.prepareToPlay(48000,block);Clock clock;clock.p.setBpm(120);clock.p.setIsPlaying(true);if(clocked)p.setPlayHead(&clock);juce::AudioBuffer<float> out(2,192000);out.clear();
    for(int offset=0;offset<out.getNumSamples();offset+=block){const int n=juce::jmin(block,out.getNumSamples()-offset);clock.p.setPpqPosition(offset/24000.);juce::AudioBuffer<float> a(2,n);juce::MidiBuffer midi;for(int k=0;k<4;++k)if(k*24000>=offset&&k*24000<offset+n)midi.addEvent(juce::MidiMessage::noteOn(1,60,(juce::uint8)110),k*24000-offset);p.processBlock(a,midi);for(int c=0;c<2;++c)out.copyFrom(c,offset,a,c,0,n);}
    p.setPlayHead(nullptr);return out;
}
float difference(const juce::AudioBuffer<float>& a,const juce::AudioBuffer<float>& b){float x=0;for(int c=0;c<2;++c)for(int i=0;i<a.getNumSamples();++i)x=juce::jmax(x,std::abs(a.getSample(c,i)-b.getSample(c,i)));return x;}
double rms(const juce::AudioBuffer<float>& a,int start,int n){double sum=0;for(int c=0;c<2;++c)for(int i=start;i<start+n;++i)sum+=double(a.getSample(c,i))*a.getSample(c,i);return std::sqrt(sum/(2*n));}
double wetSine(double hz,float hp,float lp){fkick::TechnoFX fx;fx.prepare(48000);fkick::FXSettings s;s.room=true;s.duck=0;s.fxHP=hp;s.fxLP=lp;fkick::MotionSettings motion;fkick::MotionFrame mod;fx.begin(s,motion);double energy=0;for(int i=0;i<96000;++i){const double dry=.2*std::sin(i*juce::MathConstants<double>::twoPi*hz/48000);const auto out=fx.process(dry,dry,s,mod);if(i>=72000)energy+=(out[0]-dry)*(out[0]-dry);}return std::sqrt(energy/24000);}
juce::Component* find(juce::Component& root,const juce::String& id){if(root.getComponentID()==id)return &root;for(auto* c:root.getChildren())if(auto* p=find(*c,id))return p;return nullptr;}
void shot(juce::Component& c,const juce::File& f){auto png=c.createComponentSnapshot(c.getLocalBounds());auto out=f.createOutputStream();check(out!=nullptr,"SC PNG stream");out->setPosition(0);out->truncate();check(juce::PNGImageFormat{}.writeImageToStream(png,*out),"SC PNG");}
void wave(const juce::File& f,juce::AudioBuffer<float>& a){a.applyGainRamp(a.getNumSamples()-240,240,1,0);auto out=f.createOutputStream();check(out!=nullptr,"SC WAV stream");out->setPosition(0);out->truncate();juce::WavAudioFormat fmt;std::unique_ptr<juce::AudioFormatWriter> w(fmt.createWriterFor(out.get(),48000,2,24,{},0));check(w!=nullptr,"SC WAV writer");out.release();check(w->writeFromAudioSampleBuffer(a,0,a.getNumSamples()),"SC WAV write");}
}
void runFXRackTests(const juce::File& folder){
    FKickProcessor order;const char* newIDs[]={"scShape","scShift","scMix","room","fxHP","fxLP"};check(order.getParameters().size()==131,"FX parameter count");for(int i=0;i<6;++i)check(dynamic_cast<juce::RangedAudioParameter*>(order.getParameters()[123+i])->paramID==newIDs[i],"Existing parameter order changed");
    check(dynamic_cast<juce::RangedAudioParameter*>(order.getParameters()[129])->paramID=="bassLift"&&dynamic_cast<juce::RangedAudioParameter*>(order.getParameters()[130])->paramID=="bassQ","Bass EQ must append host IDs");
    // Gerçek ses ölçümü: 300 Hz shelf merkezi yarı dB, sub tam gain, tiz unity; Q geçişi değiştirir.
    auto eqGain=[](double sr,double hz,float db,float q){fkick::BassEQ eq;eq.prepare(sr);eq.begin(db,q);double in=0,out=0;for(int i=0;i<int(sr);++i){eq.tick();const double x=.02*std::sin(juce::MathConstants<double>::twoPi*hz*i/sr),y=eq.process(0,x),r=eq.process(1,0);check(std::isfinite(y)&&r==0,"Bass EQ stability / stereo independence");if(i>int(sr/2)){in+=x*x;out+=y*y;}}return 10*std::log10(out/in);};
    // F-EQ shelf denkleminin bağımsız frekans-alanı referansları: +12 dB için 5 Hz / 10 kHz.
    // Q=.1 geniş geçiştir; bu frekanslarda ideal DC/unity varsayımı geçerli değildir.
    const double reference[4][3][2]={
        {{11.829195422,.362544517},{11.999997662,.000008478},{12.003153926,-.006958149}},
        {{11.829187578,.385846484},{11.999997662,.000009516},{12.003154075,-.007440820}},
        {{11.829155727,.483052346},{11.999997661,.000014614},{12.003154683,-.009504630}},
        {{11.829147764,.507858497},{11.999997661,.000016124},{12.003154836,-.010044649}}};
    const double rates[]={44100,48000,96000,192000};const float qualities[]={.1f,.707f,2.f};
    for(int r=0;r<4;++r)for(float db:{-12.f,12.f})for(int k=0;k<3;++k){
        check(std::abs(eqGain(rates[r],300,db,qualities[k])-db*.5)<.02,"F-EQ shelf centre mismatch");
        check(std::abs(eqGain(rates[r],5,db,qualities[k])-reference[r][k][0]*db/12)<.02,"F-EQ sub response mismatch");
        check(std::abs(eqGain(rates[r],10000,db,qualities[k])-reference[r][k][1]*db/12)<.02,"F-EQ treble response mismatch");
    }
    check(std::abs(eqGain(48000,500,12,.1f)-eqGain(48000,500,12,2))>1,"Bass Q has no effect");
    fkick::BassEQ bypass;bypass.prepare(48000);bypass.begin(0,2);for(int i=0;i<3000;++i){bypass.tick();check(bypass.process(0,.123456789)==.123456789,"Zero Bass Lift must be exact bypass");}
    // Aynı EQ'yu toplam kuru+FX dönüşüne dışarıdan uygula: dahili routing ile örnek düzeyinde eşleşmeli.
    fkick::TechnoFX plainFX,bassFX;plainFX.prepare(48000);bassFX.prepare(48000);fkick::FXSettings plainSettings,eqSettings;plainSettings.room=.6f;plainSettings.rumbleMix=.25f;plainSettings.echoMix=.2f;plainSettings.duck=0;eqSettings=plainSettings;eqSettings.bassLift=6;eqSettings.bassQ=1.2f;
    fkick::MotionSettings motionSettings;fkick::MotionFrame motionFrame;plainFX.begin(plainSettings,motionSettings);bassFX.begin(eqSettings,motionSettings);fkick::BassEQ referenceEQ;referenceEQ.prepare(48000);referenceEQ.begin(6,1.2f);
    for(int i=0;i<48000;++i){const double x=.03*std::sin(i*.01);const auto plain=plainFX.process(x,-x*.5,plainSettings,motionFrame),boosted=bassFX.process(x,-x*.5,eqSettings,motionFrame);referenceEQ.tick();for(int channel=0;channel<2;++channel)check(std::abs(boosted[(size_t)channel]-referenceEQ.process(channel,plain[(size_t)channel]))<1e-12,"Bass EQ must process dry and all FX together");}
    fkick::BassEQ moving;moving.prepare(48000);double previous=0;for(int i=0;i<48000;++i){if(i%2400==0)moving.begin(i%4800?12.f:-12.f,i%4800?2.f:.1f);moving.tick();const double y=moving.process(0,.02);check(std::isfinite(y)&&std::abs(y-previous)<.03,"Bass EQ automation jump");previous=y;}
    std::set<int> areas;for(int shape=0;shape<4;++shape){double area=0;for(int i=0;i<1000;++i){auto gain=fkick::FXShaper::curve(shape,i/1000.);check(std::isfinite(gain)&&gain>=0&&gain<=1,"SC curve range");check(std::abs(fkick::FXShaper::curve(shape,i/1000.,.2f)-fkick::FXShaper::curve(shape,i/1000.-.2f))<1e-6,"SC horizontal shift");area+=gain;}areas.insert(juce::roundToInt(area));check(fkick::FXShaper::curve(shape,0)==fkick::FXShaper::curve(shape,1),"SC loop discontinuity");}check(areas.size()==4,"Four SC shapes are not distinct");
    FKickProcessor dry,protectedDry;for(auto* p:{&dry,&protectedDry})p->setCurrentProgram(0);protectedDry.setParameter("scMix",1);protectedDry.setParameter("scShift",.2f);protectedDry.setParameter("fxHP",3000);protectedDry.setParameter("fxLP",120);check(difference(render(dry),render(protectedDry))==0,"SC/FX filters changed the dry kick");
    FKickProcessor room,none;for(auto* p:{&room,&none}){p->setCurrentProgram(0);p->setParameter("length",100);p->setParameter("duck",0);}room.setParameter("room",1);auto roomAudio=render(room),noneAudio=render(none);for(int c=0;c<2;++c)for(int i=0;i<960;++i)check(roomAudio.getSample(c,i)==noneAudio.getSample(c,i),"Room leaked a dry copy before its first reflection");check(rms(roomAudio,7000,12000)>rms(noneAudio,7000,12000)+.0002,"Room tail is inaudible");
    FKickProcessor half;half.setCurrentProgram(0);half.setParameter("length",100);half.setParameter("duck",0);half.setParameter("room",.5f);auto halfAudio=render(half);
    for(int c=0;c<2;++c)for(int i=0;i<roomAudio.getNumSamples();++i){roomAudio.getWritePointer(c)[i]-=noneAudio.getSample(c,i);halfAudio.getWritePointer(c)[i]-=noneAudio.getSample(c,i);}
    check(std::abs(rms(halfAudio,7000,12000)/rms(roomAudio,7000,12000)-.5)<.001,"Room Mix must scale wet continuously");
    check(dynamic_cast<juce::AudioParameterFloat*>(half.state.getParameter("room"))!=nullptr,"Room remains a boolean parameter");
    const double low=wetSine(80,0,20000),cutLow=wetSine(80,800,20000),high=wetSine(2500,0,20000),cutHigh=wetSine(2500,0,200);check(low>.00001&&high>.000001&&cutLow<low*.1&&cutHigh<high*.1,"FX return HP/LP attenuation");
    FKickProcessor full,shaped,blend;for(auto* p:{&full,&shaped,&blend}){p->setCurrentProgram(68);p->setParameter("room",1);p->setParameter("duck",0);p->setParameter("tempo",120);}shaped.setParameter("scMix",1);blend.setParameter("scMix",.5f);auto a=render(full),b=render(shaped),c=render(blend);check(difference(a,b)>.005,"SC does not affect FX");check(difference(a,c)>.001&&difference(b,c)>.001,"SC Mix does not blend");
    FKickProcessor blockA,blockB;for(auto* p:{&blockA,&blockB}){p->setCurrentProgram(68);p->setParameter("room",1);p->setParameter("scMix",.85f);p->setParameter("scShift",.12f);p->setParameter("fxHP",80);p->setParameter("fxLP",5000);p->setParameter("bassLift",4.5f);p->setParameter("bassQ",1.2f);}check(difference(render(blockA,127,true),render(blockB,512,true))<2e-6,"SC/room host-clock block invariance");
    FKickProcessor sync;sync.prepareToPlay(48000,480);Clock clock;clock.p.setBpm(120);clock.p.setPpqPosition(.35);clock.p.setIsPlaying(true);sync.setPlayHead(&clock);juce::AudioBuffer<float> audio(2,480);juce::MidiBuffer midi;midi.addEvent(juce::MidiMessage::noteOn(1,60,(juce::uint8)110),0);sync.processBlock(audio,midi);check(std::abs(sync.scPhase.load()-.37)<1e-5,"SC is not host PPQ aligned");clock.p.setPpqPosition(-.25);midi.clear();sync.processBlock(audio,midi);check(std::abs(sync.scPhase.load()-.77)<1e-5,"SC transport seek or negative PPQ");clock.p.setIsPlaying(false);midi.addEvent(juce::MidiMessage::noteOn(1,60,(juce::uint8)110),0);sync.processBlock(audio,midi);check(std::abs(sync.scPhase.load()-.02)<1e-5,"SC fallback MIDI retrigger");sync.setPlayHead(nullptr);
    blockA.setParameter("room",.37f);juce::MemoryBlock state;blockA.getStateInformation(state);FKickProcessor restored;restored.setStateInformation(state.getData(),int(state.getSize()));check(difference(render(blockA,256,true),render(restored,256,true))<2e-6,"New FX state roundtrip");
    FKickProcessor legacy;const juce::File fixtures(FKICK_TEST_FIXTURES);check(legacy.loadPreset(fixtures.getChildFile("Legacy-0.5-Deep-House.fkick")),"0.5 compatibility fixture");check(legacy.value("bassLift")==0&&std::abs(legacy.value("bassQ")-.707f)<.001&&legacy.value("room")==0&&legacy.value("scMix")==0&&legacy.value("fxHP")==0&&legacy.value("fxLP")==20000,"Legacy FX bypass defaults");const auto oldWav=folder.getChildFile("F-Kick-Legacy-0.5.wav");check(legacy.exportWav(oldWav),"0.5 compatibility export");check(fkickTest::sameLegacyWav(fixtures.getChildFile("Legacy-0.5-Deep-House.wav"),oldWav),"0.5 sound changed with new FX bypassed");
    FKickProcessor visual;visual.setCurrentProgram(68);std::unique_ptr<juce::AudioProcessorEditor> ui(visual.createEditor());auto* page=dynamic_cast<juce::TextButton*>(find(*ui,"page-sidechain"));check(page!=nullptr,"SC replaced page missing");page->onClick();auto* graph=dynamic_cast<FKickSidechainGraph*>(find(*ui,"sidechain-graph"));check(graph&&graph->isVisible()&&find(*ui,"motion-preview")==nullptr&&find(*ui,"lfoShape")==nullptr,"Simple SC must replace modulation page");
    for(int i=0;i<4;++i){auto* button=dynamic_cast<juce::TextButton*>(find(*ui,"sc-preset-"+juce::String(i+1)));check(button&&button->isVisible(),"SC preset button missing");button->onClick();check(visual.value("scShape")==i,"SC preset selection");}
    auto* mix=dynamic_cast<juce::Label*>(find(*ui,"scMix-value"));auto* shift=dynamic_cast<juce::Label*>(find(*ui,"scShift-value"));mix->showEditor();mix->getCurrentTextEditor()->setText("75%");mix->hideEditor(false);shift->showEditor();shift->getCurrentTextEditor()->setText("-25%");shift->hideEditor(false);check(std::abs(visual.value("scMix")-.75f)<.001&&std::abs(visual.value("scShift")+.25f)<.001,"SC typed controls");
    const auto time=juce::Time::getCurrentTime();auto event=[&](float x,bool dragged){return juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),{x,60},juce::ModifierKeys(juce::ModifierKeys::leftButtonModifier),1,0,0,0,0,graph,graph,time,{100,60},time,1,dragged);};graph->mouseDown(event(100,false));graph->mouseDrag(event(228,true));graph->mouseUp(event(228,true));check(std::abs(visual.value("scShift")-(-.25f+128.f/(graph->getWidth()-36)))<.002,"SC graph horizontal drag");graph->mouseDoubleClick(event(100,false));check(visual.value("scShift")==0,"SC graph double-click reset");shot(*ui,folder.getChildFile("F-Kick-sidechain.png"));
    visual.setParameter("scShift",.25f);visual.setParameter("scShape",2);shot(*ui,folder.getChildFile("F-Kick-sidechain-shift.png"));auto* fxPage=dynamic_cast<juce::TextButton*>(find(*ui,"page-fx"));fxPage->onClick();auto* roomText=dynamic_cast<juce::Label*>(find(*ui,"room-value"));check(roomText&&roomText->isVisible(),"Room Mix numeric control missing");roomText->showEditor();roomText->getCurrentTextEditor()->setText("50%");roomText->hideEditor(false);check(std::abs(visual.value("room")-.5f)<.001f,"Room Mix typed value");
    auto* hp=dynamic_cast<juce::Label*>(find(*ui,"fxHP-value"));auto* lp=dynamic_cast<juce::Label*>(find(*ui,"fxLP-value"));hp->showEditor();hp->getCurrentTextEditor()->setText("65");hp->hideEditor(false);lp->showEditor();lp->getCurrentTextEditor()->setText("5k");lp->hideEditor(false);check(std::abs(visual.value("fxHP")-65)<.02f&&std::abs(visual.value("fxLP")-5000)<.05f,"FX filter typed controls");shot(*ui,folder.getChildFile("F-Kick-room-filter.png"));
    auto bounds=[&](const char* id){auto* c=find(*ui,id);check(c!=nullptr,"Column control missing");return ui->getLocalArea(c,c->getLocalBounds());};
    const auto rm=bounds("room"),hpb=bounds("fxHP"),lpb=bounds("fxLP"),sample=bounds("envelope-editor");
    const auto bass=bounds("bassLift"),bq=bounds("bassQ");
    check(rm.getX()==hpb.getX()&&hpb.getY()==lpb.getY()&&hpb.getRight()<lpb.getX()&&rm.getBottom()<hpb.getY(),"HP/LP must share row below Room");
    check(bass.getY()==bq.getY()&&bass.getRight()<bq.getX()&&hpb.getBottom()<bass.getY(),"Bass Lift/Q row below filters");
    auto* liftText=dynamic_cast<juce::Label*>(find(*ui,"bassLift-value"));auto* qText=dynamic_cast<juce::Label*>(find(*ui,"bassQ-value"));
    liftText->showEditor();liftText->getCurrentTextEditor()->setText("+6 dB");liftText->hideEditor(false);qText->showEditor();qText->getCurrentTextEditor()->setText("1.20");qText->hideEditor(false);
    check(std::abs(visual.value("bassLift")-6)<.001&&std::abs(visual.value("bassQ")-1.2f)<.001,"Bass EQ typed values");shot(*ui,folder.getChildFile("F-Kick-bass-eq.png"));
    check(sample.getHeight()>126&&sample.getRight()<rm.getX()&&sample.getBottom()>=lpb.getBottom(),"Sample display does not fill the column height");
    auto* sampleGraph=dynamic_cast<FKickGraph*>(find(*ui,"envelope-editor"));check(sampleGraph&&sampleGraph->plotBounds().getHeight()>94,"Waveform drawing height did not increase");
    ui->setVisible(true); // JUCE hit-test yalnız görünür component ağaçlarında çalışır; native pencere açılmaz.
    for(const char* id:{"sampleGain-value","sampleTune-value","samplePan-value","start-value","end-value"}){auto* c=find(*ui,id);auto* hit=ui->getComponentAt(ui->getLocalPoint(c,c->getLocalBounds().getCentre()));check(hit==c||c->isParentOf(hit),"Graph blocks inline sample controls");}
    check(find(*ui,"lfoShape")==nullptr&&find(*ui,"mod-target")==nullptr,"Other modulation controls remain");
    for(int shape=0;shape<4;++shape){FKickProcessor demo;demo.setCurrentProgram(68);demo.setParameter("room",1);demo.setParameter("scMix",1);demo.setParameter("scShape",float(shape));demo.setParameter("fxHP",40);demo.setParameter("fxLP",3500);auto sound=render(demo,257,true);const auto demoFile=folder.getChildFile("F-Kick-SC-"+juce::String(shape+1)+".wav");wave(demoFile,sound);if(shape==0){check(fkickTest::sameLegacyWav(fixtures.getChildFile("Legacy-0.6-Room-On.wav"),demoFile),"Room Mix 100% no longer matches legacy On");}}
    check(folder.getChildFile("FX_RACK_METRICS.txt").replaceWithText("Room low sine wet RMS: "+juce::String(low,7)+"; HP 800 Hz: "+juce::String(cutLow,7)+"\nRoom high sine wet RMS: "+juce::String(high,7)+"; LP 200 Hz: "+juce::String(cutHigh,7)+"\nDry change with sidechain and return filters: 0\nPPQ, negative seek, MIDI fallback and 127/512 blocks: passed\n"),"FX report");
    std::cout<<"PASS Bass EQ frequency response / Q / stereo / bypass / multi-rate / state / layout\n";
    std::cout<<"PASS four SC curves / graph drag / Mix / FX-only dry protection / room / return HP-LP / host PPQ / MIDI fallback / state / 0.5 compatibility\n";
}
